<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
$error=null;$success=null;$values=[];
try{$pdo=business_db();security_step17_ensure($pdo);$actor=security_step17_current_user($pdo);if(!security_step17_has_permission($pdo,'security.roles.manage',$actor))throw new RuntimeException('Administrator permission is required.');$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$idle=max(300,min(7200,(int)($_POST['idle_seconds']??1800)));$absolute=max(3600,min(172800,(int)($_POST['absolute_seconds']??43200)));$attempts=max(3,min(10,(int)($_POST['attempt_limit']??5)));$window=max(300,min(3600,(int)($_POST['window_seconds']??900)));$lock=max(300,min(3600,(int)($_POST['lock_seconds']??900)));if($absolute<=$idle)throw new RuntimeException('Absolute timeout must be greater than idle timeout.');$stmt=$pdo->prepare("INSERT INTO security_settings(organization_id,setting_key,setting_value) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");foreach(['idle_timeout_seconds'=>$idle,'absolute_timeout_seconds'=>$absolute,'login_attempt_limit'=>$attempts,'login_window_seconds'=>$window,'login_lock_seconds'=>$lock] as $k=>$v)$stmt->execute([$orgId,$k,(string)$v]);$pdo->prepare("UPDATE security_sessions SET revoked_at=NOW(),revoke_reason='security_policy_changed' WHERE organization_id=? AND revoked_at IS NULL AND user_id<>?")->execute([$orgId,(int)$actor['id']]);security_step17_audit($pdo,(int)$actor['id'],'security_policy_updated','organization',$orgId,['idle_seconds'=>$idle,'absolute_seconds'=>$absolute,'attempt_limit'=>$attempts,'window_seconds'=>$window,'lock_seconds'=>$lock]);$success='Security policy updated. Other users must sign in again.';}$stmt=$pdo->prepare("SELECT setting_key,setting_value FROM security_settings WHERE organization_id=?");$stmt->execute([$orgId]);foreach($stmt->fetchAll() as $r)$values[$r['setting_key']]=(int)$r['setting_value'];}catch(Throwable $e){$error=$e->getMessage();$csrf=$csrf??'';}
function ss17min(int $v):string{return number_format($v/60,0).' min';}function ss17hr(int $v):string{return number_format($v/3600,1).' hr';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security Policy - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="security_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 17 • Security Policy</small></span></a><div class="os-top-actions"><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><main class="os-main" style="max-width:900px;margin:24px auto"><section class="os-hero pp-hero"><div class="os-kicker">SESSION + LOGIN POLICY</div><h1>Configure security timeouts without editing code.</h1><p>Values are bounded to safe operating ranges. Policy changes revoke other active sessions so the new controls apply cleanly.</p></section><?php if($error):?><div class="pp-alert bad"><?= security_step17_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= security_step17_h($success) ?></div><?php endif;?><section class="os-card"><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= security_step17_h($csrf) ?>"><label>Idle Timeout<select name="idle_seconds"><?php foreach([300,600,900,1800,3600,7200] as $v):?><option value="<?= $v ?>" <?= ($values['idle_timeout_seconds']??1800)===$v?'selected':'' ?>><?= ss17min($v) ?></option><?php endforeach;?></select></label><label>Absolute Session Timeout<select name="absolute_seconds"><?php foreach([3600,14400,28800,43200,86400,172800] as $v):?><option value="<?= $v ?>" <?= ($values['absolute_timeout_seconds']??43200)===$v?'selected':'' ?>><?= ss17hr($v) ?></option><?php endforeach;?></select></label><label>Failed Login Limit<select name="attempt_limit"><?php foreach(range(3,10) as $v):?><option value="<?= $v ?>" <?= ($values['login_attempt_limit']??5)===$v?'selected':'' ?>><?= $v ?> attempts</option><?php endforeach;?></select></label><label>Failure Counting Window<select name="window_seconds"><?php foreach([300,600,900,1800,3600] as $v):?><option value="<?= $v ?>" <?= ($values['login_window_seconds']??900)===$v?'selected':'' ?>><?= ss17min($v) ?></option><?php endforeach;?></select></label><label>Lock Period<select name="lock_seconds"><?php foreach([300,600,900,1800,3600] as $v):?><option value="<?= $v ?>" <?= ($values['login_lock_seconds']??900)===$v?'selected':'' ?>><?= ss17min($v) ?></option><?php endforeach;?></select></label><button>Save Security Policy</button></form></section></main></body></html>